public enum BoundKind { Closed, Open, Unbounded }

public readonly record struct Interval<T>(T Lo, T Hi, BoundKind LoKind, BoundKind HiKind)
    where T : IComparable<T>
{
    public static Interval<DateOnly> ClosedOpen(DateOnly lo, DateOnly hi) =>
        new(lo, hi, BoundKind.Closed, BoundKind.Open);

    public bool Contains(T v) =>
        (LoKind == BoundKind.Open ? v.CompareTo(Lo) > 0 : v.CompareTo(Lo) >= 0) &&
        (HiKind == BoundKind.Open ? v.CompareTo(Hi) < 0 : v.CompareTo(Hi) <= 0);
}

